var b=document.querySelector('[aria-label="Increase font size"]');
if (b) {
  b.focus();
  var r=b.getBoundingClientRect();
  ['pointerover','pointerenter','mouseover','mouseenter','mousemove','pointermove'].forEach(function(t){
    var E = (t.indexOf('pointer')===0 && window.PointerEvent) ? PointerEvent : MouseEvent;
    b.dispatchEvent(new E(t,{bubbles:true,cancelable:true,clientX:r.left+5,clientY:r.top+5,pointerType:'mouse',pointerId:1,isPrimary:true}));
  });
}
